	@Test
	void unsignedOracleIncludesEmptyDuplicateAndWindowBoundaryDomains() throws Exception {
		Random random = new Random(20260905);
		for (int trial = 0; trial < 60; trial++) {
			Domain[] domains = new Domain[trial % 11];
			var oracle = new HashSet<Long>();
			for (int p = 0; p < domains.length; p++) {
				var values = new HashSet<Long>();
				for (int i = 0; i < trial % 27; i++) {
					long key = switch (i % 5) {
					case 0 -> random.nextLong();
					case 1 -> Long.MIN_VALUE + random.nextInt(4);
					case 2 -> -1L;
					case 3 -> 0L;
					default -> (1L << 20) + random.nextInt(4) - 2;
					};
					values.add(key);
					oracle.add(key);
				}
				domains[p] = DistinctRootCountCandidates.array(values.stream()
						.mapToLong(v -> v ^ Long.MIN_VALUE)
						.sorted()
						.map(v -> v ^ Long.MIN_VALUE)
						.toArray());
			}
			for (int workers : new int[] { 1, 2, 4, 8 }) {
				System.setProperty("rdf4j.lmdb.parallel.threads", Integer.toString(workers));
				Source source = new Source(domains);
				var result = count(source, new NativeCancellationToken());
				assertThat(result.count()).as("trial %s workers %s", trial, workers).isEqualTo(oracle.size());
				assertThat(result.scratchBytes()).isLessThanOrEqualTo(LmdbNativeDistinctRootCount.MEMORY_LIMIT);
				assertThat(source.openCursors.get()).isZero();
				assertThat(source.closedSiblings.get()).isEqualTo(source.openedSiblings.get());
			}
		}
	}

