	@Test
	void cancellationAndWorkerFailureJoinReadersBeforeClosingSnapshots() throws Exception {
		System.setProperty("rdf4j.lmdb.parallel.threads", "2");
		for (boolean fail : new boolean[] { false, true }) {
			Source source = new Source(DistinctRootCountCandidates.fixture(100000, 8, "INTERLEAVED", "DENSE"));
			source.requireJoinedReaders = true;
			var entered = new CountDownLatch(1);
			var release = new CountDownLatch(1);
			var reads = new AtomicInteger();
			NativeCancellationToken token = new NativeCancellationToken();
			source.beforeRead = () -> {
				if (reads.getAndIncrement() == 0) {
					entered.countDown();
					await(release);
				} else if (fail) {
					throw new IllegalStateException("injected root reader failure");
				}
			};
			try (var executor = Executors.newSingleThreadExecutor()) {
				var future = executor.submit(() -> count(source, token));
				try {
					assertThat(entered.await(10, TimeUnit.SECONDS)).isTrue();
					if (!fail) {
						token.requestCancellation();
					}
					assertThat(future.isDone()).isFalse();
					release.countDown();
					if (fail) {
						assertThatThrownBy(() -> future.get(10, TimeUnit.SECONDS))
								.hasRootCauseMessage("injected root reader failure");
					} else {
						assertThatThrownBy(() -> future.get(10, TimeUnit.SECONDS))
								.hasCauseInstanceOf(KernelQueryCancelledException.class);
					}
					assertThat(source.openCursors.get()).isZero();
					assertThat(source.closedSiblings.get()).isEqualTo(2);
				} finally {
					release.countDown();
				}
			}
		}
	}

