	static LmdbNativeDistinctRootCount.Result count(Source source, NativeCancellationToken token) throws Exception {
		try (var probe = source.newProbe()) {
			NativeAdjacency[] views = new NativeAdjacency[source.domains.length];
			long[] predicates = new long[views.length];
			for (int p = 0; p < views.length; p++) {
				predicates[p] = p;
				views[p] = probe.adjacency(p, false);
			}
			return LmdbNativeDistinctRootCount.count(source, predicates, views, false, token);
		}
	}

	private static void await(CountDownLatch latch) {
		try {
			if (!latch.await(10, TimeUnit.SECONDS)) {
				throw new AssertionError("latch timed out");
			}
		} catch (InterruptedException failure) {
			Thread.currentThread().interrupt();
			throw new AssertionError(failure);
		}
	}

