	private static final class Sibling extends Source implements NativeLmdbQuerySource.ParallelSource {
		final Source parent;

		Sibling(Source parent) {
			super(parent.domains);
			this.parent = parent;
		}

		@Override
		public NativeProbe newProbe() {
			if (parent.workerViewsAvailable) {
				return parent.newProbe();
			}
			return new NativeProbe() {
				@Override
				public RecordIterator open(long s, long p, long o, long c) {
					throw new UnsupportedOperationException();
				}

				@Override
				public void close() {
				}
			};
		}

		@Override
		public void close() {
			if (parent.requireJoinedReaders && parent.openCursors.get() != 0) {
				throw new AssertionError("snapshot closed before reader join");
			}
			parent.closedSiblings.incrementAndGet();
		}
	}

